export class TimeSystem{constructor(){this.minutes=480;this.speed=4}update(dt){this.minutes=(this.minutes+dt*this.speed)%1440}get hours(){return Math.floor(this.minutes/60)}get mins(){return Math.floor(this.minutes%60)}get formatted(){return String(this.hours).padStart(2,"0")+":"+String(this.mins).padStart(2,"0")}get period(){if(this.hours<6)return"night";if(this.hours<9)return"morning";if(this.hours<18)return"day";if(this.hours<21)return"evening";return"night"}}
